create table if not exists war_ads (id bigint generated by default as identity primary key, wallet text, image_url text, ad_link text, ad_name text, x numeric, y numeric, w numeric, h numeric, amount_paid numeric default 0, payment_type text default 'paid', created_at timestamptz default now());
create table if not exists chat_messages (id bigint generated by default as identity primary key, wallet text, message text, created_at timestamptz default now());
create table if not exists voucher_codes (id bigint generated by default as identity primary key, code text unique not null, tier text, value numeric, used boolean default false, disabled boolean default false, used_by text, created_at timestamptz default now(), used_at timestamptz);
